def solve(grid):
    """
    Transform the input grid according to the discovered rule.

    For each non‑zero colour (shape) the function:
      * finds the bounding box of the shape,
      * chooses the horizontal direction (left/right) that has the larger empty
        space,
      * chooses the vertical direction (up/down) that has the larger empty space,
      * searches the smallest shift (>= width+1 horizontally, >= height+1 vertically)
        that makes all placed cells (cells that would be written into an empty
        position) not be orthogonal or diagonal neighbours of any cell of a
        different colour,
      * writes the three copies (horizontal, vertical, both) into the grid,
        leaving existing non‑zero cells untouched.
    """
    H = len(grid)
    W = len(grid[0]) if H else 0

    # ------------------------------------------------------------------
    # collect shapes
    from collections import defaultdict
    colour_cells = defaultdict(list)
    for r in range(H):
        for c in range(W):
            v = grid[r][c]
            if v:
                colour_cells[v].append((r, c))

    # ------------------------------------------------------------------
    # helper: check whether a given shift is admissible
    def shift_ok(cells, h_sign, h_off, v_sign, v_off, colour, original):
        """
        Returns True iff every cell that would be placed by the shift does not
        become orthogonal or diagonal neighbours of a cell of a different colour.
        Overlap with a different colour is permitted – those cells are simply not
        written.
        """
        # directions to test
        copies = []
        if h_off and not v_off:
            copies.append(('h', h_sign, h_off, 0))
        elif v_off and not h_off:
            copies.append(('v', 0, v_sign, v_off))
        elif h_off and v_off:
            copies.append(('b', h_sign, h_off, v_sign, v_off))
        else:
            return False

        for typ in copies:
            if typ[0] == 'h':
                _, hs, ho, _ = typ
                for r, c in cells:
                    nr = r
                    nc = c + hs * ho
                    if not (0 <= nr < H and 0 <= nc < W):
                        continue
                    if original[nr][nc] != 0 and original[nr][nc] != colour:
                        # overlapped – this cell will simply be ignored
                        continue
                    # placed cell – check 8‑neighbour adjacency
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr2, nc2 = nr + dr, nc + dc
                            if 0 <= nr2 < H and 0 <= nc2 < W:
                                if original[nr2][nc2] != 0 and original[nr2][nc2] != colour:
                                    return False
            elif typ[0] == 'v':
                _, vs, vo, _ = typ
                for r, c in cells:
                    nr = r + vs * vo
                    nc = c
                    if not (0 <= nr < H and 0 <= nc < W):
                        continue
                    if original[nr][nc] != 0 and original[nr][nc] != colour:
                        continue
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr2, nc2 = nr + dr, nc + dc
                            if 0 <= nr2 < H and 0 <= nc2 < W:
                                if original[nr2][nc2] != 0 and original[nr2][nc2] != colour:
                                    return False
            else:   # both
                _, hs, ho, vs, vo = typ
                for r, c in cells:
                    nr = r + vs * vo
                    nc = c + hs * ho
                    if not (0 <= nr < H and 0 <= nc < W):
                        continue
                    if original[nr][nc] != 0 and original[nr][nc] != colour:
                        continue
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if dr == 0 and dc == 0:
                                continue
                            nr2, nc2 = nr + dr, nc + dc
                            if 0 <= nr2 < H and 0 <= nc2 < W:
                                if original[nr2][nc2] != 0 and original[nr2][nc2] != colour:
                                    return False
        return True

    # ------------------------------------------------------------------
    # process every colour
    for colour, cells in colour_cells.items():
        rows = [r for r, _ in cells]
        cols = [c for _, c in cells]
        min_r, max_r = min(rows), max(rows)
        min_c, max_c = min(cols), max(cols)

        width  = max_c - min_c + 1
        height = max_r - min_r + 1

        # ----- choose horizontal direction (more empty space)
        left_space  = min_c
        right_space = W - 1 - max_c
        if left_space >= right_space:
            h_sign = -1          # move left
            max_h_off = left_space
        else:
            h_sign = 1           # move right
            max_h_off = right_space

        # ----- choose vertical direction (more empty space)
        up_space   = min_r
        down_space = H - 1 - max_r
        if up_space >= down_space:
            v_sign = -1          # move up
            max_v_off = up_space
        else:
            v_sign = 1           # move down
            max_v_off = down_space

        h_min = width + 1
        v_min = height + 1

        # search the smallest offsets that satisfy the adjacency rule
        best_h = None
        best_v = None
        found = False
        # we allow the offset to be a bit larger than the distance to the border
        # (by at most the other dimension) – this covers the cases where the
        # copy is allowed to exceed the border and be truncated.
        for ho in range(h_min, max_h_off + height + 1):
            for vo in range(v_min, max_v_off + width + 1):
                if ho == 0 and vo == 0:
                    continue
                if shift_ok(cells, h_sign, ho, v_sign, vo, colour, grid):
                    best_h, best_v = ho, vo
                    found = True
                    break
            if found:
                break

        # if no offset works we leave the shape unchanged
        if not found:
            continue

        # ----- apply the three copies
        # horizontal only
        for r, c in cells:
            nr = r
            nc = c + h_sign * best_h
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == 0:
                grid[nr][nc] = colour
        # vertical only
        for r, c in cells:
            nr = r + v_sign * best_v
            nc = c
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == 0:
                grid[nr][nc] = colour
        # both
        for r, c in cells:
            nr = r + v_sign * best_v
            nc = c + h_sign * best_h
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == 0:
                grid[nr][nc] = colour

    return grid

